value.out/kit.tar.gz!/manifest.json:
{
  "schemaVersion": 1,
  "profileName": "kit",
  "createdBy": {
    "tool": "nomoreide",
    "version": "%%VERSION%%"
  },
  "credentials": [
    {
      "key": "a_secret",
      "required": true,
      "description": "Environment variable A_SECRET required for MCP access"
    },
    {
      "key": "z_token",
      "required": true,
      "description": "Environment variable Z_TOKEN required for MCP access"
    },
    {
      "key": "api_key",
      "required": true,
      "description": "Environment variable APIKey required for MCP access"
    },
    {
      "key": "http_token",
      "required": true,
      "description": "Environment variable HTTPToken required for MCP access"
    },
    {
      "key": "xml_secret",
      "required": true,
      "description": "Environment variable XMLSecret required for MCP access"
    },
    {
      "key": "authorization",
      "required": true,
      "description": "Header Authorization required for MCP access"
    },
    {
      "key": "b_token",
      "required": true,
      "description": "Environment variable B_TOKEN required for MCP access"
    },
    {
      "key": "m_password",
      "required": true,
      "description": "Header M-Password required for MCP access"
    }
  ]
}

